x}.role-card.selected .role-icon{background:var(--accent);color:white}.role-title{font-size:13px;font-weight:700}.role-copy{font-size:10px;color:var(--text-faint);margin-top:3px}.two-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.strength{height:4px;border-radius:3px;background:var(--surface-hover);overflow:hidden;margin-top:7px}.strength span{display:block;width:0;height:100%;transition:.2s}.terms{display:flex;gap:8px;align-items:flex-start;font-size:10.5px;line-height:1.45;color:var(--text-faint)}.terms input{accent-color:var(--accent);margin-top:2px}.auth-bottom{text-align:center;font-size:12px;color:var(--text-faint);margin-top:18px}@media(max-width:900px){.auth-page{grid-template-columns:1fr}.auth-visual{display:none}.auth-main{min-height:100vh;padding:26px 18px}}@media(max-width:520px){.role-grid,.two-fields{grid-template-columns:1fr}.auth-main{padding:22px 14px}.auth-heading{font-size:23px}}</style></head><body>
