<div class="two-fields"><div><label class="label">Имя и фамилия</label><div class="input-icon-wrap"><span class="input-icon"><x-icon name="user" :size="16"/></span><input class="input" required name="name" value="{{ old('name') }}" placeholder="Ваше имя" autocomplete="name"></div></div><div><label class="label">Телефон</label><div class="input-icon-wrap"><span class="input-icon"><x-icon name="user" :size="16"/></span><input class="input" name="phone" value="{{ old('phone') }}" placeholder="+993 61 00 00 00" autocomplete="tel"></div></div></div>
