<div><label class="label">Электронная почта</label><div class="input-icon-wrap"><span class="input-icon"><x-icon name="mail" :size="16"/></span><input class="input" required type="email" name="email" value="{{ old('email') }}" placeholder="name@example.com" autocomplete="username"></div></div>
<div class="two-fields"><div><label class="label">Пароль</label><div class="input-icon-wrap"><span class="input-icon"><x-icon name="lock" :size="16"/></span><input class="input has-toggle" required type="password" name="password" id="reg-password" placeholder="Минимум 8 символов" autocomplete="new-password" oninput="checkStrength(this.value)"><button type="button" class="input-toggle" onclick="togglePassword(this,'reg-password')"><span class="pw-show"><x-icon name="eye" :size="16"/></span><span class="pw-hide" style="display:none"><x-icon name="eye-off" :size="16"/></span></button></div><div class="strength"><span id="strength-bar"></span></div></div><div><label class="label">Повторите пароль</label><div class="input-icon-wrap"><span class="input-icon"><x-icon name="lock" :size="16"/></span><input class="input has-toggle" required type="password" name="password_confirmation" id="reg-confirm" placeholder="Повторите пароль" autocomplete="new-password"><button type="button" class="input-toggle" onclick="togglePassword(this,'reg-confirm')"><span class="pw-show"><x-icon name="eye" :size="16"/></span><span class="pw-hide" style="display:none"><x-icon name="eye-off" :size="16"/></span></button></div></div></div>
