<script>function selectRole(role){document.getElementById('role-card-customer').classList.toggle('selected',role==='customer');document.getElementById('role-card-seller').classList.toggle('selected',role==='seller');const field=document.getElementById('store-name-field'),input=field.querySelector('input');field.style.display=role==='seller'?'block':'none';input.required=role==='seller'}selectRole(@json(old('role','customer')));function togglePassword(btn,id){const i=document.getElementById(id),hidden=i.type==='password';i.type=hidden?'text':'password';btn.querySelector('.pw-show').style.display=hidden?'none':'flex';btn.querySelector('.pw-hide').style.display=hidden?'flex':'none'}function checkStrength(v){let score=0;if(v.length>=8)score++;if(/[A-ZА-Я]/.test(v)&&/[a-zа-я]/.test(v))score++;if(/\d/.test(v))score++;if(/[^\wа-яА-Я]/.test(v))score++;const bar=document.getElementById('strength-bar'),colors=['var(--danger)','var(--warning)','var(--warning)','var(--success)'];bar.style.width=(score*25)+'%';bar.style.background=colors[Math.max(0,score-1)]}</script></body></html>
